-- Twin Val'kyr: Bullet Controller and Bullet Stalkers drive the Concentrated Light/Darkness orbs
DELETE FROM `creature` WHERE `id` IN (34704, 34720, 34743) AND `guid` BETWEEN 141600 AND 141688;

-- Orbs walk and run at 7 yd/s
UPDATE `creature_template` SET `faction` = 2189, `speed_walk` = 2.8, `speed_run` = 1, `VerifiedBuild` = 50664 WHERE `entry` IN (34628, 34630);

-- Burst summons only come from stalkers of the matching colour
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 13 AND `SourceEntry` IN (66140, 67158, 67159, 67160, 66141, 67161, 67162, 67163);

DELETE FROM `spell_script_names` WHERE `spell_id` = 100101 AND `ScriptName` = 'spell_valkyr_ball_periodic_dummy_aura';
DELETE FROM `spell_script_names` WHERE `spell_id` IN (66312, 66314, 66149, 68396, 66077, 67152, 67153, 67154);

DELETE FROM `spell_dbc` WHERE `ID` = 100101;
